package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.exception.NonMonotonousSequenceException;
import org.apache.commons.math.exception.util.Localizable;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for {@link MathUtils#equals(double, double)}
 */
public class MathUtils_equals_TriageGen1Test {

    @Test
    public void testEquals_BothNaN() {
        // Tests the (Double.isNaN(x) && Double.isNaN(y)) branch
        assertTrue("Both NaN should be equal", MathUtils.equals(Double.NaN, Double.NaN));
    }

    @Test
    public void testEquals_IdenticalValues() {
        // Tests the x == y branch
        assertTrue("Identical positive values should be equal", MathUtils.equals(1.0, 1.0));
        assertTrue("Identical negative values should be equal", MathUtils.equals(-5.5, -5.5));
        assertTrue("Identical zero values should be equal", MathUtils.equals(0.0, 0.0));
        assertTrue("Identical infinity values should be equal", MathUtils.equals(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY));
    }

    @Test
    public void testEquals_DifferentValues() {
        // Tests the case where both conditions are false
        assertFalse("Different values should not be equal", MathUtils.equals(1.0, 2.0));
        assertFalse("One positive and one negative should not be equal", MathUtils.equals(1.0, -1.0));
    }

    @Test
    public void testEquals_OneNaN() {
        // Tests the case where only one is NaN (isNaN(x) && isNaN(y) is false, and x == y is false)
        assertFalse("One NaN and one number should not be equal", MathUtils.equals(Double.NaN, 1.0));
        assertFalse("One number and one NaN should not be equal", MathUtils.equals(1.0, Double.NaN));
    }

    @Test
    public void testEquals_ZeroSignDifference() {
        // In IEEE 754, 0.0 == -0.0 is true. 
        // This tests the x == y branch for signed zeros.
        assertTrue("Positive zero and negative zero should be equal per x == y", MathUtils.equals(0.0, -0.0));
    }
}
